sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
	if (isLoading || newValue === '') {
		return;
	}

	var messages = {
		laptop: 'A laptop is required to perform daily work tasks and access company applications.',
		monitor: 'An additional monitor is required to improve productivity and multitasking.',
		chair: 'An ergonomic chair is required to maintain proper posture during working hours.',
		mouse: 'A mouse is required for efficient navigation and interaction with applications.',
		keyboard: 'A keyboard is required for typing, coding, and documentation.',
		ups: 'A UPS is required to provide temporary backup power during power interruptions.'
	};

	g_form.setValue('justification', messages[newValue] || '');
}
